@app.post("/test-order-1")
async def test_order_1(form_val: str = Form(), file_val: UploadFile = File()):
    return {"form_val": form_val, "file_val": file_val.filename}

@app.post("/test-order-2")
async def test_order_2(file_val: UploadFile = File(), form_val: str = Form()):
    return {"form_val": form_val, "file_val": file_val.filename}

@app.post("/test-multiple-files")
async def test_multiple_files(
    form_val: str = Form(), 
    file1: UploadFile = File(), 
    file2: UploadFile = File()
):
    return {"form_val": form_val, "file1": file1.filename, "file2": file2.filename}

client = TestClient(app)

def test_order_1():
    response = client.post(
        "/test-order-1",
        data={"form_val": "hello"},
        files={"file_val": ("test.txt", b"content")}
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "test.txt"}

def test_order_2():
    response = client.post(
        "/test-order-2",
        data={"form_val": "hello"},
        files={"file_val": ("test.txt", b"content")}
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "test.txt"}

